-- Total raw_materials et distribution par catégorie
SELECT category, COUNT(*) as cnt FROM raw_materials GROUP BY category ORDER BY cnt DESC;

-- Vérifier si molecule_id 810043 existe (test ghost-variety-links)
SELECT id, name FROM molecules WHERE id = 810043;

-- Vérifier le premier ghost_variety_molecule_link (test should have valid molecule references)
SELECT gvml.id, gvml.ghost_variety_id, gvml.molecule_id, m.name 
FROM ghost_variety_molecule_links gvml 
LEFT JOIN molecules m ON gvml.molecule_id = m.id 
LIMIT 3;

